test('invoiceTotals: calculates subtotal and total for multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, vatRate: 21 },
      { qty: 1, unitPrice: 120000, vatRate: 21 },
      { qty: 100, unitPrice: 37, vatRate: 9 },
    ],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // Subtotal: 42500 + 120000 + 3700 = 166200
  assert.equal(result.value.subtotal, 166200);
  // VAT: (42500 + 120000) * 21% + 3700 * 9% = 34005 + 333 = 34338
  assert.equal(result.value.vat, 34338);
  // Total: 166200 + 34338 = 200538
  assert.equal(result.value.total, 200538);
});

