test('invoiceTotals: calculates total as subtotal - discount + vat', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, vatRate: 21, discountPercent: 10 }],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // subtotal = 100000, discount = 10000, vat = 21% of 90000 = 18900
  // total = 100000 - 10000 + 18900 = 108900
  assert.equal(result.value.subtotal, 100000);
  assert.equal(result.value.discount, 10000);
  assert.equal(result.value.vat, 18900);
  assert.equal(result.value.total, 108900);
});

test('invoiceTotals: sums VAT from multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, vatRate: 21 },
      { qty: 100, unitPrice: 1000, vatRate: 9 },
    ],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // Line 1: 21% of 100000 = 21000
  // Line 2: 9% of 100000 = 9000
  // Total VAT = 30000
  assert.equal(result.value.vat, 30000);
  assert.equal(result.value.total, 230000);
});

test('invoiceTotals: calculates VAT correctly with mixed VAT rates and discounts', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, vatRate: 21, discountPercent: 10 },
      { qty: 100, unitPrice: 1000, vatRate: 9 },
      { qty: 100, unitPrice: 1000, vatRate: 0 },
    ],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // Line 1: 90000 taxable, 21% = 18900
  // Line 2: 100000 taxable, 9% = 9000
  // Line 3: 100000 taxable, 0% = 0
  // Total VAT = 27900
  // Total = (100000 + 100000 + 100000) - 10000 + 27900 = 317900
  assert.equal(result.value.vat, 27900);
  assert.equal(result.value.total, 317900);
});

test('invoiceTotals: VAT exempt items show zero VAT', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, vatRate: 0 }],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  assert.equal(result.value.vat, 0);
  assert.equal(result.value.total, 100000);
});

test('invoiceTotals: VAT not affected by tier discount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // C-001 is gold tier (5% discount)
  // Line total: 100 * 9500 = 950000
  // Discount: 950000 * 5% = 47500
  // Taxable: 950000 - 47500 = 902500
  // VAT: 902500 * 21% = 189525
  assert.equal(result.value.subtotal, 950000);
  assert.equal(result.value.discount, 47500);
  assert.equal(result.value.vat, 189525);
  assert.equal(result.value.total, 1092025);
});

